mapper.select:
SELECT w.id, w.task_id, t.title AS task_title, w.project_id, p.name AS project_name, w.user_id, u.real_name AS user_name, w.work_date, w.hours, w.description, w.status, w.auditor_id, au.real_name AS auditor_name, w.audit_remark, w.audit_time, w.create_time FROM t_worklog w LEFT JOIN t_task t ON w.task_id = t.id LEFT JOIN project p ON w.project_id = p.id LEFT JOIN sys_user u ON w.user_id = u.id LEFT JOIN sys_user au ON w.auditor_id = au.id
AND w.project_id = #{projectId} AND w.user_id = #{userId} AND w.status = #{status}
ORDER BY w.work_date DESC, w.id DESC

SELECT
    w.work_date AS workDate,
    SUM(w.hours) AS totalHours
FROM t_worklog w
WHERE w.status = 1
AND w.project_id = #{projectId}
AND w.work_date >= #{startDate}
AND w.work_date <= #{endDate}
GROUP BY w.work_date
ORDER BY w.work_date ASC
